WITH flattened AS (SELECT id, plan, EXPLODE_OUTER(tier_limits) AS tier_value FROM price_tiers) SELECT CASE WHEN tier_value >= 85 THEN 'HIGH' ELSE 'LOW' END AS tier_value_tier, APPROX_PERCENTILE(tier_value, ARRAY(0.25, 0.5, 0.75)) AS tier_value_quartiles, APPROX_PERCENTILE(tier_value, ARRAY(0.25, 0.5, 0.75)) AS tier_value_quartiles_2, ROUND(AVG(tier_value), 2) AS avg_tier_value FROM flattened GROUP BY tier_value_tier ORDER BY avg_tier_value DESC NULLS LAST;
